contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to receive refunded ether when C transfers to us
    receive() external payable {}

    // Single public test function taking blockNumberMod15 and amount to send
    function run(uint someBlockNumberModulo15, uint amount) public payable {
        require(address(this).balance >= amount);
        // precondition: only consider calls that send exactly 10 ether to c, otherwise C's fallback will revert
        // we will use amount parameter and require it's 10 ether so the call should not revert for that reason
        require(amount == 10 ether);

        // record before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // To model both cases of block.number % 15 == 0 and != 0, the caller provides someBlockNumberModulo15
        // We cannot change block.number here; this param just documents expectation. The property will quantify
        // behavior based on the actual observed post-state.

        // Perform the call that may revert; capture revert status
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule asserted:
        // - If the call reverted, pastBlockTime and balance remain unchanged.
        // - If the call did not revert: pastBlockTime must equal current block.timestamp (>= beforePast)
        //   and either (a) if block.number % 15 == 0 then contract forwarded its entire balance to this caller making afterBal == 0,
        //   or (b) if block.number % 15 != 0 then contract retained the 10 ether increasing its balance by exactly 10 ether.
        assert(
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            || (
                !reverted
                && afterPast == block.timestamp
                && ( (block.number % 15 == 0 && afterBal == 0)
                     || (block.number % 15 != 0 && afterBal == beforeBal + 10 ether) )
            )
        );
    }
}

