contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // helper to receive refunds from C during fallback-triggered transfers
    receive() external payable {}

    // The single public property-based test function
    function run(uint sendAmount) public payable {
        // require our contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // record observable state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // perform the external call to C's fallback by sending Ether and empty calldata
        bool reverted;
        // We must make the state-changing call at top level
        try c.f{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        /* General rule asserted:
           - If the call reverted, no further guarantees about state changes (but revert flag true).
           - If the call did not revert:
             * pastBlockTime is non-decreasing (afterPast >= beforePast) and equal to block.timestamp
               iff the fallback executed its require(block.timestamp > pastBlockTime) path and succeeded.
             * If sendAmount == 10 ether and block.number % 15 == 0 then C may have sent all its balance to this contract,
               so afterBalance is either 0 (if transfer happened) or >= 0 otherwise. We assert the invariant that
               either the contract's balance decreased by at most beforeBalance (i.e., not negative), and if a transfer
               occurred it exactly emptied the contract (afterBalance == 0). Since we cannot directly detect the transfer
               except via balances, we assert that if sendAmount == 10 ether and not reverted and afterPast == block.timestamp
               and block.number % 15 == 0 then afterBalance == 0 OR afterBalance == beforeBalance + sendAmount - beforeBalance;
               the latter simplifies to afterBalance == 0. To keep the assert purely over observed values we state:
             * If call succeeded then afterPast >= beforePast and (sendAmount != 10 ether || block.number % 15 != 0 || afterBalance == 0 || afterBalance == beforeBalance + sendAmount);
           The final assert encodes these relations.
        */

        assert(
            // if reverted, just allow (no further condition)
            reverted
            || (
                // non-reverted: past time must not decrease
                afterPast >= beforePast
                // and afterPast is either unchanged or set to current block.timestamp (which is >= beforePast)
                && (
                    // either past didn't change
                    afterPast == beforePast
                    // or it was updated to the current block timestamp
                    || afterPast == block.timestamp
                )
                // and balance behavior: afterBalance is never negative (always true), and in the special case
                // of exactly 10 ether sent on a block divisible by 15, the contract may have emptied itself (afterBalance==0)
                && (
                    sendAmount != 10 ether
                    || block.number % 15 != 0
                    || afterBalance == 0
                )
            )
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // allow receiving refunds if C sends Ether back
    receive() external payable {}

    // single public property test
    function run(uint sendAmount) public payable {
        // ensure this contract can forward sendAmount
        require(address(this).balance >= sendAmount);

        // observe before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // perform the external low-level call to trigger C's fallback
        bool reverted;
        bytes memory ret;
        (reverted, ret) = address(c).call{value: sendAmount}("");

        // observe after-values
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // General rule asserted in one assert:
        // - If the call reverted, no further conditions required.
        // - If the call did not revert: pastBlockTime must not decrease (afterPast >= beforePast).
        //   Additionally, if exactly 10 ether was sent and block.number % 15 == 0, then C may have emptied itself
        //   as part of the fallback, so afterBalance is allowed to be 0; otherwise no specific balance drop is required.
        assert(
            reverted
            || (
                // non-reverted: pastBlockTime non-decreasing
                afterPast >= beforePast
                // and balance behavior: if special-case (10 ether & block%15==0) then afterBalance can be 0,
                // but otherwise we don't assert a forced drain. We still ensure afterBalance is a valid uint (always true),
                // so encode that for non-special-case no contradiction is required by allowing any afterBalance.
                && (sendAmount != 10 ether || block.number % 15 != 0 || afterBalance == 0)
            )
        );
    }
}

