contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We implement the test in a single public payable function taking amount and a timestamp-advancing flag.
    // amount: how much wei we send to c in the fallback call
    // advanceBlocks: a dummy uint to make inputs symbolic; advancing block.number/time is not possible here,
    // but the property will relate observed pastBlockTime before and after the call.
    function run(uint amount, uint advanceBlocks) public payable {
        // ensure this contract has enough balance to send `amount`
        require(address(this).balance >= amount);

        // read before-value
        uint before = c.pastBlockTime();

        // perform the call and capture whether it reverted
        bool reverted;
        // call fallback by sending value to c (no data)
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-value
        uint after = c.pastBlockTime();

        // General rule:
        // - If the call reverted, pastBlockTime must be unchanged (after == before).
        // - If the call did not revert, then the call must have been sent with exactly 10 ether
        //   and the contract should have updated pastBlockTime to a strictly greater value (after > before).
        assert( (reverted && after == before)
                || (!reverted && amount == 10 ether && after > before) );
    }

    // Allow this test contract to receive Ether so it can forward it to c.
    receive() external payable {}

    // Minimal low-level wrapper to invoke fallback of C by calling its address.
    // We must not declare other functions, so we use this internal helper pattern via the low-level call above.
}

