contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // send amount to C's fallback by calling payable fallback through low-level call is disallowed by shape rules,
    // so we invoke the fallback by using address(c).call in a top-level statement is not allowed either.
    // Instead, we trigger the fallback by using try/catch on a plain external payable call to c with empty calldata.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-value
        uint before = c.pastBlockTime();

        // perform call to fallback: must be a top-level state-changing interaction on c using try/catch
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-value
        uint afterVal = c.pastBlockTime();

        // General rule: either reverted and pastBlockTime unchanged, or succeeded only when amount == 10 ether and pastBlockTime increased
        assert((reverted && afterVal == before) || (!reverted && amount == 10 ether && afterVal > before));
    }

    // receive to accept refunds/transfers if contract drains funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters: amount to send and a simulated block timestamp and block number cannot be set here,
    // but we can observe effects dependent on block.timestamp and block.number. We therefore test with variable amount and observe revert or state change.
    function run(uint256 amount) public payable {
        // require we have the funds available to forward to c
        require(address(this).balance >= amount, "insufficient balance for test");

        // read before-values
        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterPast = c.pastBlockTime();
        uint256 afterBal = address(c).balance;

        // General rule as a single assert:
        // If the call reverted then either amount != 10 ether or block.timestamp <= beforePast.
        // If it did not revert then amount == 10 ether, afterPast == block.timestamp, and either (if block.number % 15 == 0) c forwarded entire balance so afterBal == 0 and this contract received greater balance than before, or (if block.number % 15 != 0) c kept previous balance plus the sent amount.
        // We express this as one boolean formula below, using only observable values.
        assert(
            reverted
            ? (amount != 10 ether || block.timestamp <= beforePast)
            : (
                // successful call implies amount was 10 ether and pastBlockTime updated to current timestamp
                amount == 10 ether && afterPast == block.timestamp && (
                    // two mutually exclusive outcomes based on block.number % 15
                    (block.number % 15 == 0
                        ? (afterBal == 0)
                        : (afterBal == beforeBal + amount)
                    )
                )
            )
        );
    }

    // allow receiving refunds/transfers from C when it pays out
    receive() external payable {}
}

