            // If call reverted, then either amount != 10 ether or timestamp did not increase
            (!ok && (amount != 10 ether || block.timestamp <= beforePast))
            // If call succeeded, amount must be exactly 10 ether, pastBlockTime updated to block.timestamp,
            // and balance either becomes 0 when block.number%15==0 or increases by exactly amount otherwise.
            || (ok && amount == 10 ether && afterPast == block.timestamp && (
                (block.number % 15 == 0 && afterBal == 0)
                || (block.number % 15 != 0 && afterBal == beforeBal + amount)
            ))
        );
    }

